head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > P > preventCopyPaste]<br/>입력값에 대한 복사, 잘라내기, 붙여넣기를 금지할지 설정합니다.",
    "validation" : [
        "true 설정 시 드래그 앤 드롭이 금지됩니다.",
        "true 설정 시 컨텍스트 메뉴(마우스 우클릭, contextmenu)가 차단됩니다.",
        "false (default) 설정 시 드래그 앤 드롭과 컨텍스트 메뉴를 허용합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 재생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label_guide !== 'undefined') {
        label_guide.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof paste_input !== 'undefined') {
        paste_input.remove();
    }

    let preventCopyPaste = con_preventCopyPaste.getText();

    // 조건 설정 (style 은 createBasicTextArea 내부에서 자동 부여 → 중복 정의 금지)
    let properties = {
        preventCopyPaste: preventCopyPaste,
    }

    let cList = $c.gcm.createCList(properties);

    await $c.gcm.createLabel('label="■  dragdrop 검증 : 입력창의 test 문자열을 전체 선택한 후 textarea 영역으로 드래그 앤 드랍하여 차단 여부 확인"', '', 'label1');

    await $c.gcm.createBasicTextArea(cList, '', 'target1');

    target1.setValue("드래그·우클릭 차단 검증용 textarea");

    // 복사 값 붙여넣기 테스트 용 input 생성 (복사할 초기값 설정)
    $c.gcm.createBasicInput('', '', 'paste_input');
    paste_input.setValue("test");

    // 우클릭(contextmenu) 발생 + 메뉴 표시 여부 감지 listener 등록 (capture phase 로 WebSquare native 핸들러보다 먼저 실행)
    target1.render.addEventListener('contextmenu', function (e) {
        // setTimeout(0) 으로 native 핸들러의 preventDefault 호출 이후 시점에서 defaultPrevented 확인
        setTimeout(function () {
            wf_body_bottom.getObj("scwin").setReturnValue(
                "[contextmenu] 우클릭 감지 → defaultPrevented : " + e.defaultPrevented +
                " (true = 컨텍스트 메뉴 차단됨 / false = 메뉴 표시됨)"
            );
        }, 0);
    }, true);
}



// target/입력창의 현재 값을 출력
scwin.btn_getReturn_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target1     text : " + target1.render.value);
    wf_body_bottom.getObj("scwin").setReturnValue("paste_input text : " + paste_input.render.value);
};
